enum CubeginError: Swift.Error, Equatable, Hashable, Foundation.LocalizedError {

    
    
    case InvalidInput(reason: String
    )
    case Computation(reason: String
    )

    

    

    
    public var errorDescription: String? {
        String(reflecting: self)
    }
    
}

