extension CubeginError: Sendable {}
#endif

#if swift(>=5.8)
@_documentation(visibility: private)
#endif
public struct FfiConverterTypeCubeginError: FfiConverterRustBuffer {
    typealias SwiftType = CubeginError

    public static func read(from buf: inout (data: Data, offset: Data.Index)) throws -> CubeginError {
        let variant: Int32 = try readInt(&buf)
        switch variant {

        

        
        case 1: return .InvalidInput(
            reason: try FfiConverterString.read(from: &buf)
            )
        case 2: return .Computation(
            reason: try FfiConverterString.read(from: &buf)
            )

         default: throw UniffiInternalError.unexpectedEnumCase
        }
    }

    public static func write(_ value: CubeginError, into buf: inout [UInt8]) {
        switch value {

        

        
        
        case let .InvalidInput(reason):
            writeInt(&buf, Int32(1))
            FfiConverterString.write(reason, into: &buf)
            
        
        case let .Computation(reason):
            writeInt(&buf, Int32(2))
            FfiConverterString.write(reason, into: &buf)
            
        }
    }
}


